text:
## Relevant Memories
The following are relevant memories from previous conversations:

${js}

${t.join("\n")}

Use these memories to provide more personalized and contextual responses. Note: memories marked as "(temporary)" may be outdated - use them with appropriate caution and consider their creation time.

NOTE: This is only the small subset of memories auto-retrieved for the current message — NOT your complete memory, and it may be missing something relevant. Don't rely on it alone: if you need something not covered here, don't assume it doesn't exist — run `alma memory search "<query>"` / `alma memory grep "<keyword>"` to recall more, and see the "Your Retrievable Context" section in your instructions for the other context stores you can search.

(() => {
  if (window.__almaIabInspect) { try { window.__almaIabInspect.cleanup(); } catch (e) {} }
  const Z = 2147483647;
  const box = document.createElement('div');
  box.style.cssText = 'position:fixed;z-index:' + Z + ';pointer-events:none;border:1.5px solid rgba(97,175,239,0.9);background:rgba(97,175,239,0.12);border-radius:4px;display:none;box-sizing:border-box;margin:0;padding:0;box-shadow:0 0 0 3px rgba(97,175,239,0.16),0 6px 20px rgba(40,90,160,0.24);';
  const badge = document.createElement('div');
  badge.style.cssText = 'position:fixed;z-index:' + Z + ';pointer-events:none;background:rgba(24,28,34,0.92);color:#dcdfe4;font:600 11px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace;padding:2px 8px;border-radius:7px;border:1px solid rgba(255,255,255,0.08);display:none;max-width:70vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;box-shadow:0 6px 18px rgba(0,0,0,0.45);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);margin:0;';
  document.documentElement.appendChild(box);
  document.documentElement.appendChild(badge);
  // Freeform region marquee (drag in pick phase): dashed box, page-anchored.
  const marquee = document.createElement('div');
  marquee.style.cssText = 'position:fixed;z-index:' + Z + ';pointer-events:none;border:1.5px dashed rgba(97,175,239,0.95);background:rgba(97,175,239,0.10);display:none;box-sizing:border-box;margin:0;padding:0;';
  document.documentElement.appendChild(marquee);
  let dragStart = null;    // {x,y viewport at mousedown; px,py page coords}
  let marqueeOn = false;   // true once the drag passed the slop threshold
  let suppressClick = false; // swallow the click that follows a marquee mouseup
  const prevCursor = document.documentElement.style.cursor;
  document.documentElement.style.cursor = 'crosshair';
  let current = null;   // element under the cursor (pick phase)
  let picked = null;    // element being annotated right now
  let editIndex = -1;   // queue index the panel is editing, or -1 for a new one
  let phase = 'pick';   // 'pick' = choosing an element · 'edit' = writing a note
  const queue = [];     // [{ el, message }] — the batch of changes to send

  // Floating review panel. In 'edit' it anchors to the element being annotated
  // (icon + selector + textarea); after "Add" it drops to a docked bar at the
  // bottom listing the queued changes with a Send button, so the user can mark
  // several elements and submit them together. Styling lives in a scoped
  // <style> (all rules prefixed .alma-eip-*) for :hover / :focus / ::placeholder
  // states + entrance animation; frosted glass + layered shadows for a refined,
  // native-feeling surface.
  try { const stale = document.getElementById('__almaIabInspectStyle'); if (stale) stale.remove(); } catch (e) {}
  const styleEl = document.createElement('style');
  styleEl.id = '__almaIabInspectStyle';
  styleEl.textContent = [
    '.alma-eip-panel{position:fixed;z-index:2147483647;display:none;flex-direction:column;gap:11px;width:302px;max-width:92vw;padding:14px;box-sizing:border-box;color:#dcdfe4;text-align:left;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;font-size:13px;line-height:1.5;background:rgba(33,37,43,0.94);border:1px solid rgba(255,255,255,0.11);border-radius:16px;box-shadow:0 16px 44px -18px rgba(0,0,0,0.6),0 4px 12px -8px rgba(0,0,0,0.4);-webkit-backdrop-filter:blur(24px) saturate(1.4);backdrop-filter:blur(24px) saturate(1.4);}',
    '.alma-eip-panel.alma-eip-dock{left:0;right:0;bottom:18px;top:auto;margin-inline:auto;}',
    '.alma-eip-panel.alma-eip-in{animation:almaEipIn .22s cubic-bezier(0.16,1,0.3,1);}',
    '@keyframes almaEipIn{from{opacity:0;transform:translateY(9px) scale(0.965);}to{opacity:1;transform:none;}}',
    '.alma-eip-head{display:flex;align-items:center;gap:8px;min-width:0;padding:0 2px;}',
    '.alma-eip-ico{flex:none;display:inline-flex;align-items:center;justify-content:center;width:15px;height:15px;color:#61afef;}',
    '.alma-eip-ico svg{width:15px;height:15px;display:block;}',
    '.alma-eip-panel.alma-eip-dock .alma-eip-ico{animation:almaEipPulse 1.9s ease-in-out infinite;}',
    '@keyframes almaEipPulse{0%,100%{opacity:1;transform:scale(1);}50%{opacity:0.5;transform:scale(0.88);}}',
    '.alma-eip-tag{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:ui-monospace,"SF Mono",Menlo,monospace;font-size:11.5px;letter-spacing:0.2px;color:#8b92a4;}',
    '.alma-eip-panel.alma-eip-dock .alma-eip-tag{font-family:inherit;font-size:12.5px;letter-spacing:0.1px;color:#c1c6d0;}',
    '.alma-eip-close{flex:none;width:22px;height:22px;margin-right:-3px;padding:0;border-radius:7px;display:inline-flex;align-items:center;justify-content:center;color:#8b92a4;background:transparent;border:none;cursor:pointer;font-size:17px;line-height:1;transition:background .14s ease,color .14s ease;}',
    '.alma-eip-close:hover{background:rgba(255,255,255,0.09);color:#dcdfe4;}',
    '.alma-eip-input{width:100%;box-sizing:border-box;resize:none;min-height:68px;max-height:180px;background:rgba(255,255,255,0.045);color:#dcdfe4;caret-color:#61afef;border:1px solid rgba(255,255,255,0.11);border-radius:11px;padding:10px 12px;font:inherit;outline:none;transition:border-color .16s ease,box-shadow .16s ease,background .16s ease;}',
    '.alma-eip-input::placeholder{color:#6b7383;}',
    '.alma-eip-input:focus{border-color:rgba(97,175,239,0.5);background:rgba(255,255,255,0.06);box-shadow:0 0 0 3px rgba(97,175,239,0.12);}',
    '.alma-eip-panel.alma-eip-dock .alma-eip-input,.alma-eip-panel.alma-eip-dock .alma-eip-add{display:none;}',
    '.alma-eip-list{display:none;flex-direction:column;gap:5px;max-height:150px;overflow-y:auto;margin:-1px 0;}',
    '.alma-eip-row{display:flex;align-items:center;gap:8px;padding:6px 6px 6px 8px;border-radius:9px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.06);cursor:pointer;transition:background .14s ease,border-color .14s ease;}',
    '.alma-eip-row:hover{background:rgba(255,255,255,0.075);border-color:rgba(97,175,239,0.4);}',
    '.alma-eip-rn{flex:none;width:18px;height:18px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font:700 10.5px/1 inherit;color:#c9e3fb;background:rgba(97,175,239,0.18);border:1px solid rgba(97,175,239,0.32);}',
    '.alma-eip-rsel{flex:none;max-width:92px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:ui-monospace,"SF Mono",Menlo,monospace;font-size:11px;color:#8b92a4;}',
    '.alma-eip-rnote{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#9ba3b4;font-size:12px;}',
    '.alma-eip-rx{flex:none;width:19px;height:19px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;color:#8b92a4;background:transparent;border:none;cursor:pointer;font-size:15px;line-height:1;transition:background .14s ease,color .14s ease;}',
    '.alma-eip-rx:hover{background:rgba(181,107,111,0.2);color:#cf8b8f;}',
    '.alma-eip-foot{display:flex;align-items:center;gap:8px;justify-content:flex-end;}',
    '.alma-eip-btn{display:inline-flex;align-items:center;gap:6px;appearance:none;-webkit-appearance:none;cursor:pointer;font:600 12.5px/1 inherit;letter-spacing:0.2px;border-radius:10px;padding:8px 14px;border:1px solid transparent;transition:transform .12s ease,background .16s ease,color .16s ease,box-shadow .16s ease,opacity .16s ease,filter .16s ease;}',
    '.alma-eip-btn:active:not(:disabled){filter:brightness(0.94);}',
    '.alma-eip-btn:disabled{cursor:default;opacity:0.5;}',
    '.alma-eip-add{margin-right:auto;}',
    '.alma-eip-ghost{background:transparent;color:#8b92a4;}',
    '.alma-eip-ghost:hover:not(:disabled){background:rgba(255,255,255,0.07);color:#dcdfe4;}',
    '.alma-eip-primary{color:#0c111a;background:#61afef;}',
    '.alma-eip-primary:hover:not(:disabled){background:#7bbcf3;}',
    '.alma-eip-primary:disabled{background:rgba(255,255,255,0.055);color:#5f6a7e;transform:none;box-shadow:none;opacity:1;}',
    '.alma-eip-btn svg{width:13px;height:13px;display:block;}',
    '.alma-eip-panel.alma-eip-light{color:#252a33;background:rgba(252,252,254,0.97);border:1px solid rgba(0,0,0,0.10);box-shadow:0 16px 44px -18px rgba(0,0,0,0.28),0 4px 12px -8px rgba(0,0,0,0.16);}',
    '.alma-eip-light .alma-eip-tag{color:#6b7280;}',
    '.alma-eip-light.alma-eip-dock .alma-eip-tag{color:#3d4450;}',
    '.alma-eip-light .alma-eip-close{color:#6b7280;}',
    '.alma-eip-light .alma-eip-close:hover{background:rgba(0,0,0,0.06);color:#252a33;}',
    '.alma-eip-light .alma-eip-input{background:rgba(0,0,0,0.04);color:#1f2430;border-color:rgba(0,0,0,0.12);caret-color:#3b82d9;}',
    '.alma-eip-light .alma-eip-input::placeholder{color:#9aa1ad;}',
    '.alma-eip-light .alma-eip-input:focus{background:rgba(0,0,0,0.05);border-color:rgba(59,130,217,0.55);box-shadow:0 0 0 3px rgba(59,130,217,0.14);}',
    '.alma-eip-light .alma-eip-row{background:rgba(0,0,0,0.035);border-color:rgba(0,0,0,0.07);}',
    '.alma-eip-light .alma-eip-row:hover{background:rgba(0,0,0,0.06);border-color:rgba(59,130,217,0.45);}',
    '.alma-eip-light .alma-eip-rsel{color:#6b7280;}',
    '.alma-eip-light .alma-eip-rnote{color:#57606c;}',
    '.alma-eip-light .alma-eip-rn{color:#2563a8;background:rgba(59,130,217,0.12);border-color:rgba(59,130,217,0.3);}',
    '.alma-eip-light .alma-eip-ghost{color:#6b7280;}',
    '.alma-eip-light .alma-eip-ghost:hover:not(:disabled){background:rgba(0,0,0,0.06);color:#252a33;}',
    '.alma-eip-light .alma-eip-rx:hover{background:rgba(180,60,66,0.12);color:#b53c42;}',
    '.alma-eip-light .alma-eip-primary{color:#ffffff;background:#3b82d9;}',
    '.alma-eip-light .alma-eip-primary:hover:not(:disabled){background:#4f8fde;}',
    '.alma-eip-light .alma-eip-primary:disabled{background:rgba(0,0,0,0.05);color:#9aa1ad;}'
  ].join('');
  (document.head || document.documentElement).appendChild(styleEl);

  // The panel ships dark-glass styling; over a LIGHT page that reads as a
  // washed-out gray blob. Sample the page background's luminance once at
  // inject time and flip to the light variant when the page is light.
  function pageIsLight() {
    try {
      const parse = function (bg) {
        if (!bg || bg.indexOf('rgb') !== 0) return null;
        const parts = bg.slice(bg.indexOf('(') + 1, bg.indexOf(')')).split(',').map(function (x) { return parseFloat(x); });
        if (parts.length >= 4 && parts[3] <= 0.4) return null; // (semi)transparent
        return parts;
      };
      const c = parse(getComputedStyle(document.body).backgroundColor) || parse(getComputedStyle(document.documentElement).backgroundColor);
      if (!c) return true; // unstyled pages default to white
      return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2] > 140;
    } catch (e) { return true; }
  }

  const panel = document.createElement('div');
  panel.className = 'alma-eip-panel' + (pageIsLight() ? ' alma-eip-light' : '');
  const head = document.createElement('div');
  head.className = 'alma-eip-head';
  const ico = document.createElement('span');
  ico.className = 'alma-eip-ico';
  ico.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12.034 12.681a.498.498 0 0 1 .647-.647l9 3.5a.5.5 0 0 1-.033.943l-3.444 1.068a1 1 0 0 0-.66.66l-1.067 3.443a.5.5 0 0 1-.943.033z"/><path d="M5 3a2 2 0 0 0-2 2"/><path d="M19 3a2 2 0 0 1 2 2"/><path d="M5 21a2 2 0 0 1-2-2"/><path d="M9 3h1"/><path d="M9 21h2"/><path d="M14 3h1"/><path d="M3 9v1"/><path d="M21 9v2"/><path d="M3 14v1"/></svg>';
  const title = document.createElement('span');
  title.className = 'alma-eip-tag';
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'alma-eip-close';
  closeBtn.setAttribute('aria-label', 'Close');
  closeBtn.textContent = '\u00d7';
  head.appendChild(ico); head.appendChild(title); head.appendChild(closeBtn);
  const ta = document.createElement('textarea');
  ta.className = 'alma-eip-input';
  ta.setAttribute('placeholder', 'Describe what should change\u2026');
  ta.rows = 3;
  const list = document.createElement('div');
  list.className = 'alma-eip-list';
  const foot = document.createElement('div');
  foot.className = 'alma-eip-foot';
  const addBtn = document.createElement('button');
  addBtn.type = 'button';
  addBtn.className = 'alma-eip-btn alma-eip-ghost alma-eip-add';
  addBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M12 5v14"/><path d="M5 12h14"/></svg><span>Add</span>';
  const sendBtn = document.createElement('button');
  sendBtn.type = 'button';
  sendBtn.className = 'alma-eip-btn alma-eip-primary';
  sendBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="M13 6l6 6-6 6"/></svg><span>Send</span>';
  const sendLabel = sendBtn.querySelector('span');
  foot.appendChild(addBtn); foot.appendChild(sendBtn);
  panel.appendChild(head); panel.appendChild(ta); panel.appendChild(list); panel.appendChild(foot);
  document.documentElement.appendChild(panel);

  function syncButtons() {
    const curLen = ta.value.trim().length;
    addBtn.disabled = curLen === 0;
    // In edit mode a fresh element (editIndex < 0) with text counts as +1;
    // when editing an existing item it's already in the queue.
    const pending = queue.length + (phase === 'edit' && editIndex < 0 && curLen > 0 ? 1 : 0);
    sendBtn.disabled = pending === 0;
    if (sendLabel) sendLabel.textContent = pending > 1 ? 'Send ' + pending : 'Send';
  }

  function renderList() {
    list.textContent = '';
    if (!queue.length) { list.style.display = 'none'; return; }
    list.style.display = 'flex';
    queue.forEach(function (q, i) {
      const r = document.createElement('div'); r.className = 'alma-eip-row';
      const n = document.createElement('span'); n.className = 'alma-eip-rn'; n.textContent = String(i + 1);
      const sel = document.createElement('span'); sel.className = 'alma-eip-rsel'; sel.textContent = shortLabel(q.el);
      const note = document.createElement('span'); note.className = 'alma-eip-rnote'; note.textContent = q.message;
      const x = document.createElement('button'); x.type = 'button'; x.className = 'alma-eip-rx'; x.textContent = '\u00d7';
      x.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); removeItem(i); });
      r.addEventListener('click', function (e) { e.stopPropagation(); enterEdit(q.el); });
      r.appendChild(n); r.appendChild(sel); r.appendChild(note); r.appendChild(x);
      list.appendChild(r);
    });
  }

  // A user-drawn region masquerading as a pickable element: it carries a
  // PAGE-anchored rect and quacks like an element for the few methods the
  // pick/edit flow needs (getBoundingClientRect keeps it glued to content
  // while scrolling).
  function makeRegion(pr) {
    return {
      __almaRegion: true,
      pageRect: pr,
      getBoundingClientRect: function () {
        const l = pr.x - scrollX, t = pr.y - scrollY;
        return { x: l, y: t, left: l, top: t, width: pr.width, height: pr.height, right: l + pr.width, bottom: t + pr.height };
      }
    };
  }

  function shortLabel(el) {
    if (el.__almaRegion) return 'region ' + Math.round(el.pageRect.width) + '×' + Math.round(el.pageRect.height);
    let s = el.tagName.toLowerCase();
    if (el.id) s += '#' + el.id;
    else if (el.classList.length) s += '.' + [...el.classList].slice(0, 3).join('.');
    return s;
  }

  function boxTo(el) {
    const r = el.getBoundingClientRect();
    box.style.borderStyle = el.__almaRegion ? 'dashed' : 'solid';
    box.style.display = 'block';
    box.style.left = r.left + 'px'; box.style.top = r.top + 'px';
    box.style.width = r.width + 'px'; box.style.height = r.height + 'px';
    return r;
  }

  function positionPanel(r) {
    panel.style.display = 'flex';
    const pw = panel.offsetWidth || 302;
    const ph = panel.offsetHeight || 140;
    let left = r.left;
    if (left + pw > innerWidth - 8) left = innerWidth - pw - 8;
    if (left < 8) left = 8;
    let top = r.bottom + 8;
    if (top + ph > innerHeight - 8) top = r.top - ph - 8;
    if (top < 8) top = 8;
    panel.style.left = left + 'px';
    panel.style.top = top + 'px';
  }

  // Restart the entrance animation (replays each time the panel (re)appears).
  function playIn() {
    panel.classList.remove('alma-eip-in');
    void panel.offsetWidth;
    panel.classList.add('alma-eip-in');
  }

  function paintBadge(el, r) {
    badge.style.display = 'block';
    badge.textContent = shortLabel(el) + ' \u00b7 ' + Math.round(r.width) + '\u00d7' + Math.round(r.height);
    badge.style.left = Math.max(4, r.left) + 'px';
    badge.style.top = (r.top > 26 ? r.top - 24 : Math.min(innerHeight - 24, r.bottom + 4)) + 'px';
  }

  function onMove(e) {
    if (phase !== 'pick') return;
    if (dragStart && !(e.buttons & 1)) {
      // The button was released OUTSIDE the guest (we never saw mouseup):
      // abandon the drag instead of leaving a stuck marquee behind.
      dragStart = null;
      if (marqueeOn) { marqueeOn = false; marquee.style.display = 'none'; badge.style.display = 'none'; }
    }
    if (dragStart && (e.buttons & 1)) {
      const dx = e.clientX - dragStart.x, dy = e.clientY - dragStart.y;
      if (marqueeOn || Math.abs(dx) > 5 || Math.abs(dy) > 5) {
        marqueeOn = true;
        box.style.display = 'none';
        // Page-anchor the start corner so scrolling mid-drag stays correct.
        const sx = dragStart.px - scrollX, sy = dragStart.py - scrollY;
        const left = Math.min(sx, e.clientX), top = Math.min(sy, e.clientY);
        const w = Math.abs(e.clientX - sx), h = Math.abs(e.clientY - sy);
        marquee.style.display = 'block';
        marquee.style.left = left + 'px'; marquee.style.top = top + 'px';
        marquee.style.width = w + 'px'; marquee.style.height = h + 'px';
        badge.style.display = 'block';
        badge.textContent = '⬚ ' + Math.round(w) + '×' + Math.round(h);
        badge.style.left = Math.max(4, left) + 'px';
        badge.style.top = (top > 26 ? top - 24 : Math.min(innerHeight - 24, top + h + 4)) + 'px';
        return;
      }
    }
    const el = e.target;
    if (!(el instanceof Element) || el === box || el === badge || el === document.documentElement) return;
    if (panel.contains(el)) { box.style.display = 'none'; badge.style.display = 'none'; return; }
    current = el;
    paintBadge(el, boxTo(el));
  }

  // Figma-layers-style DOM navigation (after @flowstated): with an element
  // highlighted, walk the tree by keyboard instead of hunting with the mouse —
  // Tab/Shift+Tab across siblings, Enter into the first child, Shift+Enter out
  // to the parent. Our own overlay nodes are skipped.
  function isOwn(n) { return n === box || n === badge || n === panel; }
  function firstEl(n) { let c = n && n.firstElementChild; while (c && isOwn(c)) c = c.nextElementSibling; return c || null; }
  function nextEl(n) { let s = n && n.nextElementSibling; while (s && isOwn(s)) s = s.nextElementSibling; return s || null; }
  function prevEl(n) { let s = n && n.previousElementSibling; while (s && isOwn(s)) s = s.previousElementSibling; return s || null; }
  function parentEl(n) { const p = n && n.parentElement; return (!p || p === document.documentElement) ? null : p; }

  function navTo(el) {
    if (!el || isOwn(el)) return;
    current = el;
    // behavior:instant so the box is drawn against the settled rect even on
    // pages that set scroll-behavior:smooth.
    try { el.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' }); } catch (e) {}
    paintBadge(el, boxTo(el));
  }

  // Anchor the panel to an element and open its note editor. If the element is
  // already queued, load its note so the user edits in place.
  function enterEdit(el) {
    phase = 'edit';
    picked = el;
    current = el;
    editIndex = queue.findIndex(function (q) { return q.el === el; });
    badge.style.display = 'none';
    document.documentElement.style.cursor = prevCursor;
    panel.classList.remove('alma-eip-dock');
    title.textContent = shortLabel(el);
    ta.value = editIndex >= 0 ? queue[editIndex].message : '';
    renderList();
    syncButtons();
    positionPanel(boxTo(el));
    playIn();
    setTimeout(function () { try { ta.focus(); } catch (e) {} }, 0);
  }

  function hidePanel() {
    panel.classList.remove('alma-eip-in');
    panel.style.display = 'none';
  }

  // Leave edit mode. With a queue, drop to the docked review bar (Send button +
  // the queued changes); with nothing queued, just hide and keep picking.
  function toPick() {
    phase = 'pick';
    picked = null;
    editIndex = -1;
    box.style.display = 'none';
