// ===== Alma PTC preamble (injected) =====
import { execSync as __almaExec } from 'node:child_process';
const __ALMA_API = process.env.ALMA_API_URL || 'http://localhost:23001';
const __PTC_SESSION = process.env.ALMA_PTC_SESSION || '';
const __PTC_TOKEN = process.env.ALMA_PTC_TOKEN || '';
const __ALMA_BIN = process.env.ALMA_BIN || 'alma';

/** Call an Alma tool by name. Returns its (already cleaned) result. */
async function almaTool(name, args = {}) {
  const resp = await fetch(__ALMA_API + '/api/tools/invoke', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name, args, session: __PTC_SESSION, token: __PTC_TOKEN }),
  });
  let data = null;
  try { data = await resp.json(); } catch (_) {}
  if (!resp.ok || !data || data.error) {
    throw new Error('almaTool(' + name + ') failed: ' + ((data && data.error) || ('HTTP ' + resp.status)));
  }
  return data.result;
}

/** Discover the tools you can call. Returns an array of { name, description, inputSchema }. */
async function listTools() {
  const url = __ALMA_API + '/api/tools/list?session=' + encodeURIComponent(__PTC_SESSION) + '&token=' + encodeURIComponent(__PTC_TOKEN);
  const resp = await fetch(url);
  const data = await resp.json();
  if (!resp.ok || (data && data.error)) {
    throw new Error('listTools() failed: ' + ((data && data.error) || ('HTTP ' + resp.status)));
  }
  // The endpoint wraps the list in { tools: [...] }; return the array directly so
  // callers can do listTools().find(...)/.map(...) as the name implies.
  return Array.isArray(data) ? data : (data && data.tools) || [];
}

/** Run a shell command and return its stdout (string). */
function sh(cmd, opts = {}) {
  return __almaExec(cmd, { encoding: 'utf8', env: process.env, maxBuffer: 64 * 1024 * 1024, ...opts });
}

/** Run an `alma` CLI subcommand, e.g. alma('tool list'). Returns stdout. */
function alma(subcmd) {
  return sh(__ALMA_BIN + ' ' + subcmd);
}

globalThis.almaTool = almaTool;
globalThis.listTools = listTools;
globalThis.sh = sh;
globalThis.alma = alma;
// ===== end preamble =====

