#!/usr/bin/env node
// alma-remote-daemon — Alma's remote workspace helper.
//
// Uploaded to ~/.cache/alma/ on the remote host over the existing SSH channel and
// run as `node alma-remote-daemon.mjs --stdio`. Speaks newline-delimited JSON-RPC
// on stdin/stdout: {id, method, params} -> {id, result} | {id, error:{code,message}}.
// Dependency-free on purpose: the only remote requirement is a Node.js (>=16) or
// Bun runtime. It opens no ports — SSH stdio IS the transport.

import fs from 'node:fs/promises';
import fssync from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import readline from 'node:readline';

const PROTOCOL_VERSION = 1;
const MAX_READ_BYTES = 48 * 1024 * 1024;
const MAX_WALK_ENTRIES = 200_000;

function expandHome(p) {
    if (p === '~') return os.homedir();
    if (p && p.startsWith('~/')) return path.join(os.homedir(), p.slice(2));
    return p;
}

function statInfo(st) {
    return {
        type: st.isDirectory() ? 'directory' : st.isFile() ? 'file' : st.isSymbolicLink() ? 'symlink' : 'other',
        size: st.size,
        mtimeMs: st.mtimeMs,
    };
}

// ---------------------------------------------------------------------------
// Minimal glob → RegExp translator: supports **, *, ?, [...], {a,b} (non-nested).
// Semantics follow fast-glob closely enough for tool use: `*` never crosses `/`,
// `**` crosses directories, a pattern without `/` matches at any depth.
// ---------------------------------------------------------------------------
function globToRegExp(pattern) {
    let pat = pattern.replace(/\\/g, '/');
    if (!pat.includes('/')) pat = `**/${pat}`;
    if (pat.startsWith('./')) pat = pat.slice(2);
    let re = '';
    let i = 0;
    while (i < pat.length) {
        const c = pat[i];
        if (c === '*') {
            if (pat[i + 1] === '*') {
                // `**/` or trailing `**`
                if (pat[i + 2] === '/') {
                    re += '(?:[^/]+/)*';
                    i += 3;
                } else {
                    re += '.*';
                    i += 2;
                }
            } else {
                re += '[^/]*';
                i += 1;
            }
        } else if (c === '?') {
            re += '[^/]';
            i += 1;
        } else if (c === '[') {
            const end = pat.indexOf(']', i + 1);
            if (end === -1) {
                re += '\\[';
                i += 1;
            } else {
                let cls = pat.slice(i + 1, end);
                if (cls.startsWith('!')) cls = `^${cls.slice(1)}`;
                re += `[${cls}]`;
                i = end + 1;
            }
        } else if (c === '{') {
            const end = pat.indexOf('}', i + 1);
            if (end === -1) {
                re += '\\{';
                i += 1;
            } else {
                const alts = pat
                    .slice(i + 1, end)
                    .split(',')
                    .map(a => a.replace(/[.+^$()|\\]/g, '\\$&').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]'));
                re += `(?:${alts.join('|')})`;
                i = end + 1;
            }
        } else {
            re += c.replace(/[.+^$()|\\]/g, '\\$&');
            i += 1;
        }
    }
    return new RegExp(`^${re}$`);
}

async function walkGlob(cwd, pattern, { limit = 200, dot = true } = {}) {
    const re = globToRegExp(pattern);
    const results = [];
    let visited = 0;
    const stack = [''];
    while (stack.length > 0 && results.length < limit && visited < MAX_WALK_ENTRIES) {
        const rel = stack.pop();
        const abs = rel ? path.join(cwd, rel) : cwd;
        let entries;
        try {
            entries = await fs.readdir(abs, { withFileTypes: true });
        } catch {
            continue;
        }
        for (const entry of entries) {
            if (results.length >= limit || visited >= MAX_WALK_ENTRIES) break;
            visited += 1;
            if (!dot && entry.name.startsWith('.')) continue;
            const childRel = rel ? `${rel}/${entry.name}` : entry.name;
            const isDir = entry.isDirectory();
            if (re.test(childRel)) {
