// Mirrors electron/fileWatcher.ts ignore rules for the artifact sidebar tree.
const TREE_IGNORED = new Set(['.git', 'node_modules', '.DS_Store', '__pycache__', '.venv', 'venv', '.cache', 'dist', 'build', '.next', '.turbo']);

async function buildTree(root, rel, { showHidden = false, depth = 0 } = {}) {
    if (depth > 12) return [];
    const abs = rel ? path.join(root, rel) : root;
    let entries;
    try {
        entries = await fs.readdir(abs, { withFileTypes: true });
    } catch {
        return [];
    }
    const nodes = [];
    for (const entry of entries) {
        if (TREE_IGNORED.has(entry.name)) continue;
        if (!showHidden && entry.name.startsWith('.')) continue;
        const childRel = rel ? `${rel}/${entry.name}` : entry.name;
        if (entry.isDirectory()) {
            nodes.push({
                name: entry.name,
                path: childRel,
                type: 'directory',
                children: await buildTree(root, childRel, { showHidden, depth: depth + 1 }),
            });
        } else if (entry.isFile()) {
            let size;
            try {
                size = (await fs.stat(path.join(root, childRel))).size;
            } catch {
                /* ignore */
            }
            nodes.push({ name: entry.name, path: childRel, type: 'file', size });
        }
    }
    nodes.sort((a, b) => (a.type === b.type ? a.name.localeCompare(b.name) : a.type === 'directory' ? -1 : 1));
    return nodes;
}

