        }));
    },
    async glob({ cwd, pattern, limit, dot }) {
        return walkGlob(expandHome(cwd), pattern, { limit, dot });
    },
    async tree({ path: p, showHidden }) {
        return buildTree(expandHome(p), '', { showHidden });
    },
    async exists({ path: p }) {
        return { exists: fssync.existsSync(expandHome(p)) };
    },
};

const rl = readline.createInterface({ input: process.stdin, terminal: false });
const write = obj => process.stdout.write(`${JSON.stringify(obj)}\n`);

rl.on('line', async line => {
    if (!line.trim()) return;
    let req;
    try {
        req = JSON.parse(line);
    } catch {
        return;
    }
    const { id, method, params } = req;
    const fn = methods[method];
    if (!fn) {
        write({ id, error: { code: 'ENOMETHOD', message: `Unknown method: ${method}` } });
        return;
    }
    try {
        const result = await fn(params || {});
        write({ id, result });
    } catch (error) {
        write({ id, error: { code: error?.code || 'EUNKNOWN', message: error?.message || String(error) } });
    }
});

rl.on('close', () => process.exit(0));
process.on('SIGTERM', () => process.exit(0));

