.chart-3, [data-chart="3"] { color: var(--chart-3); fill: var(--chart-3); }
.chart-4, [data-chart="4"] { color: var(--chart-4); fill: var(--chart-4); }
.chart-5, [data-chart="5"] { color: var(--chart-5); fill: var(--chart-5); }

